draw:
const m1 = p.m1, m2 = p.m2, x2 = p.x2;
const xcm = (m1 * 0 + m2 * x2) / (m1 + m2);
const L = 10;                      // metres shown
const x0 = W * 0.10, x1 = W * 0.92;
const sx = function (xm) { return x0 + (x1 - x0) * xm / L; };
const beamY = H * 0.52;
const tilt = Math.sin(t * 1.4) * 0.012;   // gentle wobble about the pivot

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";

// axis
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(x0, H * 0.86); ctx.lineTo(x1, H * 0.86); ctx.stroke();
ctx.fillStyle = C.faint;
for (let k = 0; k <= L; k += 2) {
  const xx = sx(k);
  ctx.beginPath(); ctx.moveTo(xx, H * 0.86); ctx.lineTo(xx, H * 0.89); ctx.stroke();
  ctx.fillText(k + " m", xx, H * 0.97);
}

// pivot under the centre of mass
const px = sx(xcm);
ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.moveTo(px, beamY + 10); ctx.lineTo(px - 12, beamY + 34); ctx.lineTo(px + 12, beamY + 34);
ctx.closePath(); ctx.fill();

// beam, tilted a touch about the pivot
ctx.save();
ctx.translate(px, beamY);
ctx.rotate(tilt);
ctx.fillStyle = C.figure;
ctx.fillRect(x0 - px, -3, x1 - x0, 6);

const r1 = 6 + 14 * Math.sqrt(m1 / 10);
const r2 = 6 + 14 * Math.sqrt(m2 / 10);
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(sx(0) - px, -3 - r1, r1, 0, 6.284); ctx.fill();
ctx.beginPath(); ctx.arc(sx(x2) - px, -3 - r2, r2, 0, 6.284); ctx.fill();
ctx.fillStyle = C.paper;
ctx.fillText(m1.toFixed(1), sx(0) - px, -3 - r1 + 4);
ctx.fillText(m2.toFixed(1), sx(x2) - px, -3 - r2 + 4);
ctx.restore();

// centre-of-mass marker
ctx.strokeStyle = C.accent; ctx.lineWidth = 1.5;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(px, H * 0.12); ctx.lineTo(px, beamY + 8); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.accent;
ctx.fillText("centre of mass", px, H * 0.09);

// lever arms
ctx.strokeStyle = C.figure; ctx.lineWidth = 1;
const ay = beamY + 46;
ctx.beginPath(); ctx.moveTo(sx(0), ay); ctx.lineTo(px, ay); ctx.stroke();
ctx.beginPath(); ctx.moveTo(px, ay); ctx.lineTo(sx(x2), ay); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("d1 = " + xcm.toFixed(2) + " m", (sx(0) + px) / 2, ay - 6);
ctx.fillText("d2 = " + (x2 - xcm).toFixed(2) + " m", (px + sx(x2)) / 2, ay - 6);

out.note = "x_cm = " + xcm.toFixed(3) + " m    m1*d1 = " + (m1 * xcm).toFixed(2) +
  " kg m,  m2*d2 = " + (m2 * (x2 - xcm)).toFixed(2) + " kg m";

const M = 6.0, m1 = p.m1, m2 = M - m1;
const R = p.range;                 // full range of the unexploded shell, metres
const x1land = p.x1;               // where the light piece lands
const x2land = (M * R - m1 * x1land) / m2;

const xmax = Math.max(R, x1land, x2land) * 1.12 + 10;
const x0 = W * 0.08, xR = W * 0.95, gy = H * 0.80;
const sx = function (xm) { return x0 + (xR - x0) * xm / xmax; };
const apexY = H * 0.18;
const yOf = function (xm) {
  const u = xm / R;                // 0..1 along the parabola
  return gy - (apexY - gy) * (-4 * u * (1 - u));
};

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";

// ground
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(x0, gy); ctx.lineTo(W, gy); ctx.stroke();
ctx.fillStyle = C.faint;
for (let k = 0; k <= xmax; k += 50) {
  ctx.beginPath(); ctx.moveTo(sx(k), gy); ctx.lineTo(sx(k), gy + 4); ctx.stroke();
  ctx.fillText(k + " m", sx(k), gy + 17);
}

// the undisturbed parabola: this is the path of the centre of mass
ctx.strokeStyle = C.accent; ctx.lineWidth = 1.5;
ctx.setLineDash([5, 4]);
ctx.beginPath();
for (let i = 0; i <= 100; i++) {
  const xm = R * i / 100;
  i === 0 ? ctx.moveTo(sx(xm), yOf(xm)) : ctx.lineTo(sx(xm), yOf(xm));
}
ctx.stroke();
ctx.setLineDash([]);

// timing: 0..1 rise, 1..2 fall
const per = 3.4;
const u = (t % per) / (per / 2);
if (u <= 1) {
  const xm = R * 0.5 * u;
  ctx.fillStyle = C.ink;
  ctx.beginPath(); ctx.arc(sx(xm), yOf(xm), 6, 0, 6.284); ctx.fill();
  ctx.fillText("6.0 kg", sx(xm), yOf(xm) - 12);
} else {
  const v = u - 1;                              // 0..1 after the burst
  const xa = R / 2 + (x1land - R / 2) * v;
  const xb = R / 2 + (x2land - R / 2) * v;
  const ya = gy - (gy - apexY) * (1 - v * v);
  const xc = R / 2 + (R - R / 2) * v;
  ctx.fillStyle = C.figure;
  ctx.beginPath(); ctx.arc(sx(xa), ya, 5, 0, 6.284); ctx.fill();
  ctx.fillText(m1.toFixed(1) + " kg", sx(xa), ya - 10);
  ctx.beginPath(); ctx.arc(sx(xb), ya, 7, 0, 6.284); ctx.fill();
  ctx.fillText(m2.toFixed(1) + " kg", sx(xb), ya - 12);
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(sx(xc), yOf(xc), 4, 0, 6.284); ctx.fill();
}

// burst point
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(sx(R / 2), apexY, 3, 0, 6.284); ctx.fill();
ctx.fillText("burst", sx(R / 2), apexY - 8);

// landing marks
ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(sx(x1land), gy - 7); ctx.lineTo(sx(x1land), gy + 7); ctx.stroke();
ctx.beginPath(); ctx.moveTo(sx(x2land), gy - 7); ctx.lineTo(sx(x2land), gy + 7); ctx.stroke();
ctx.strokeStyle = C.accent;
ctx.beginPath(); ctx.moveTo(sx(R), gy - 10); ctx.lineTo(sx(R), gy + 10); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("light piece", sx(x1land), gy + 32);
ctx.fillText("heavy piece", sx(x2land), gy + 32);
ctx.fillStyle = C.accent;
ctx.fillText("cm lands here", sx(R), gy + 45);

out.note = "heavy piece lands at x = " + x2land.toFixed(1) + " m   (" +
  m1.toFixed(1) + "*" + x1land.toFixed(0) + " + " + m2.toFixed(1) + "*" +
  x2land.toFixed(1) + " = 6.0*" + R.toFixed(0) + ")";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";
const cy = H * 0.62;
const s = Math.min(W / 3.4, H) * 0.46;

function label(x, y, txt) { ctx.fillStyle = C.ink; ctx.fillText(txt, x, y); }
function dot(x, y) {
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(x, y, 4, 0, 6.284); ctx.fill();
}

// ---- half disk ----
let cx = W * 0.18;
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(cx, cy, s, Math.PI, 0); ctx.closePath(); ctx.fill();
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(cx - s - 6, cy); ctx.lineTo(cx + s + 6, cy); ctx.stroke();
dot(cx, cy - 4 * s / (3 * Math.PI));
ctx.strokeStyle = C.accent;
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx, cy - 4 * s / (3 * Math.PI)); ctx.stroke();
label(cx, cy + 20, "half disk");
ctx.fillStyle = C.accent;
ctx.fillText("4R / 3pi = 0.424 R", cx, cy + 38);
ctx.fillStyle = C.faint;
ctx.fillText("R", cx + s * 0.55, cy - 6);

// ---- solid hemisphere ----
cx = W * 0.5;
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(cx, cy, s, Math.PI, 0); ctx.closePath(); ctx.fill();
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(cx - s - 6, cy); ctx.lineTo(cx + s + 6, cy); ctx.stroke();
ctx.strokeStyle = C.paper; ctx.lineWidth = 1;
for (let i = 1; i < 5; i++) {
  const yy = cy - s * i / 5;
  const hw = Math.sqrt(Math.max(s * s - (cy - yy) * (cy - yy), 0));
  ctx.beginPath(); ctx.moveTo(cx - hw, yy); ctx.lineTo(cx + hw, yy); ctx.stroke();
}
dot(cx, cy - 3 * s / 8);
ctx.strokeStyle = C.accent; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx, cy - 3 * s / 8); ctx.stroke();
label(cx, cy + 20, "solid hemisphere");
ctx.fillStyle = C.accent;
ctx.fillText("3R / 8 = 0.375 R", cx, cy + 38);

// ---- solid cone ----
cx = W * 0.82;
ctx.fillStyle = C.figure;
ctx.beginPath();
ctx.moveTo(cx - s * 0.75, cy); ctx.lineTo(cx + s * 0.75, cy); ctx.lineTo(cx, cy - s);
ctx.closePath(); ctx.fill();
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(cx - s - 6, cy); ctx.lineTo(cx + s + 6, cy); ctx.stroke();
dot(cx, cy - s / 4);
ctx.strokeStyle = C.accent;
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx, cy - s / 4); ctx.stroke();
label(cx, cy + 20, "solid cone");
ctx.fillStyle = C.accent;
ctx.fillText("h / 4 above the base", cx, cy + 38);
ctx.fillStyle = C.faint;
ctx.fillText("h", cx + 10, cy - s * 0.7);

ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("each dot is the centre of mass; the flat face is the reference line", 10, H * 0.10);

const L = 1.0;                    // block length in units
const over2 = p.top;              // overhang of top block past the lower block, in units of L
const over1 = p.bottom;           // overhang of lower block past the table, in units of L

const scale = W * 0.30;           // pixels per block length
const tableX = W * 0.44;          // table edge
const bh = Math.max(16, H * 0.13);
const baseY = H * 0.72;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";

// table
ctx.fillStyle = C.faint;
ctx.fillRect(20, baseY, tableX - 20, H * 0.20);
ctx.fillStyle = C.ink;
ctx.fillText("table", (20 + tableX) / 2, baseY + H * 0.14);

// lower block: left end at tableX - (1 - over1)*scale
const x1 = tableX - (L - over1) * scale;
const x2 = x1 + over2 * scale;    // top block shifted further right
ctx.fillStyle = C.figure;
ctx.fillRect(x1, baseY - bh, L * scale, bh);
ctx.fillRect(x2, baseY - 2 * bh - 2, L * scale, bh);

// centres of mass
const c1 = x1 + 0.5 * scale, c2 = x2 + 0.5 * scale;
const cpair = (c1 + c2) / 2;
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(c1, baseY - bh / 2, 4, 0, 6.284); ctx.fill();
ctx.beginPath(); ctx.arc(c2, baseY - 1.5 * bh - 2, 4, 0, 6.284); ctx.fill();

// combined cm line
ctx.strokeStyle = C.accent; ctx.lineWidth = 1.5;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(cpair, H * 0.10); ctx.lineTo(cpair, baseY + 4); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.accent;
ctx.fillText("cm of the pair", cpair, H * 0.07);

// table edge line
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(tableX, H * 0.10); ctx.lineTo(tableX, baseY + H * 0.20); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("edge", tableX + 4, H * 0.16);

const topOK = c2 <= x1 + L * scale + 0.01;
const pairOK = cpair <= tableX + 0.01;
ctx.textAlign = "center";
ctx.fillStyle = C.ink;
ctx.fillText(topOK ? "top block: stable" : "top block: topples", W * 0.80, H * 0.28);
ctx.fillText(pairOK ? "pair: stable" : "pair: topples", W * 0.80, H * 0.44);

const total = (over1 + over2) * L;
out.note = "total overhang = " + total.toFixed(3) + " L" +
  ((topOK && pairOK) ? "   (stable; the limit is 0.500 + 0.250 = 0.750 L)" : "   (UNSTABLE)");
